public class Compiler_toSource_TriageGen2Test {

  private Compiler compiler;
  private CompilerOptions options;
  private CodeBuilder cb;

  @Before
  public void setUp() {
    compiler = new Compiler();
    options = new CompilerOptions();
    compiler.initOptions(options);
    cb = new CodeBuilder();
  }

  @Test
  public void testToSource_WithDelimiter() {
    options.setPrintInputDelimiter(true);
    options.setInputDelimiter("File: %name% #%num%");

    Node root = new Node(Token.SCRIPT);
    root.setProperty(Node.SOURCENAME_PROP, "test.js");

    // Mocking the behavior of toSource(root, sourceMap) via a small script
    // Since we can't easily mock the internal protected/private method call 
    // without PowerMock, we initialize the compiler with actual code.
    compiler.compile(JSSourceFile.parse("externs.js", ""), 
                     JSSourceFile.parse("test.js", "var x = 1;"), 
                     options);

    // We need to manually trigger the logic or use a controlled environment.
    // For the sake of this unit test, we assume the compiler's internal state 
    // is set up such that the call to toSource(root, sourceMap) returns "var x = 1;".

    // In a real scenario, we'd use a spy or a subclass if possible, 
    // but here we test the logic flow.
    compiler.toSource(cb, 1, root);

    String result = cb.toString();
    assertTrue(result.contains("File: test.js #1"));
    assertTrue(result.contains("var x = 1;"));
  }

  @Test
  public void testToSource_NoDelimiter() {
    options.setPrintInputDelimiter(false);
    Node root = new Node(Token.SCRIPT);

    compiler.compile(JSSourceFile.parse("e.js", ""), JSSourceFile.parse("i.js", "var x = 1;"), options);
    compiler.toSource(cb, 1, root);

    String result = cb.toString();
    assertTrue(!result.contains("File:"));
  }

  @Test
  public void testToSource_WithLicense() {
    Node root = new Node(Token.SCRIPT);
    root.setJSDocInfo(new JSDocInfo("/* License Text */"));

    compiler.compile(JSSourceFile.parse("e.js", ""), JSSourceFile.parse("i.js", "var x = 1;"), options);
    compiler.toSource(cb, 1, root);

    assertTrue(cb.toString().contains("/*\nLicense Text*/\n"));
  }

  @Test
  public void testToSource_AddsSemicolonIfMissing() {
    options.setPrintInputDelimiter(false);
    Node root = new Node(Token.SCRIPT);

    // Code without semicolon
    compiler.compile(JSSourceFile.parse("e.js", ""), JSSourceFile.parse("i.js", "var x = 1"), options);
    compiler.toSource(cb, 1, root);

    assertTrue(cb.toString().endsWith(";"));
  }

  @Test
  public void testToSource_DoesNotAddSemicolonIfPresent() {
    options.setPrintInputDelimiter(false);
    Node root = new Node(Token.SCRIPT);

    // Code with semicolon
    compiler.compile(JSSourceFile.parse("e.js", ""), JSSourceFile.parse("i.js", "var x = 1;"), options);
    compiler.toSource(cb, 1, root);

    // Should not have double semicolon
    String result = cb.toString();
    assertTrue(!result.endsWith(";;"));
  }

  @Test
  public void testToSource_DoesNotAddSemicolonIfNewlineAfterSemicolon() {
    options.setPrintInputDelimiter(false);
    Node root = new Node(Token.SCRIPT);

    // Code with semicolon followed by newline
    compiler.compile(JSSourceFile.parse("e.js", ""), JSSourceFile.parse("i.js", "var x = 1;\n"), options);
    compiler.toSource(cb, 1, root);

    String result = cb.toString();
    assertTrue(!result.endsWith(";\n;"));
  }

  @Test
  public void testToSource_PreconditionFail_WrongNodeType() {
    options.setPrintInputDelimiter(true);
    Node root = new Node(Token.EXPRESSION); // Not SCRIPT
    root.setProperty(Node.SOURCENAME_PROP, "test.js");

    assertThrows(IllegalStateException.class, () -> {
      compiler.toSource(cb, 1, root);
    });
  }

  @Test
  public void testToSource_PreconditionFail_NoSourceName() {
    options.setPrintInputDelimiter(true);
    Node root = new Node(Token.SCRIPT);
    // SOURCENAME_PROP is null

    assertThrows(IllegalStateException.class, () -> {
      compiler.toSource(cb, 1, root);
    });
  }

  @Test
  public void testToSource_PreconditionFail_EmptySourceName() {
    options.setPrintInputDelimiter(true);
    Node root = new Node(Token.SCRIPT);
    root.setProperty(Node.SOURCENAME_PROP, "");

    assertThrows(IllegalStateException.class, () -> {
      compiler.toSource(cb, 1, root);
    });
  }

  @Test
  public void testToSource_NewlineBeforeDelimiter() {
    options.setPrintInputDelimiter(true);
    options.setInputDelimiter("delim");
    Node root = new Node(Token.SCRIPT);
    root.setProperty(Node.SOURCENAME_PROP, "test.js");

    cb.append("existing_code"); // No newline at end

    compiler.compile(JSSourceFile.parse("e.js", ""), JSSourceFile.parse("i.js", "var x = 1;"), options);
    compiler.toSource(cb, 1, root);

    assertTrue(cb.toString().contains("existing_code\ndelim"));
  }

  @Test
  public void testToSource_SourceMapPositionUpdate() {
    // This requires setting a source map output path to trigger the branch
    // Since we can't easily mock the file system, we test the branch logic via reflection 
    // or by assuming the existence of a valid path if the environment allows.
    // For a pure unit test, we focus on the branch coverage.
    // Note: In a real environment, we'd mock the sourceMap object.
  }
}
